import 'dart:convert';

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';

/// One card from a bundled catalog: a real printed card, with the attributes
/// the deck builder needs already filled in.
///
/// Catalogs are generated by `tool/build_catalog.dart`. Entries use short keys
/// to keep the asset small; [_aliases] maps them back to the attribute names
/// the game definitions use, and any key not listed passes through unchanged so
/// another game can add attributes of its own.
class CatalogCard {
  const CatalogCard({
    required this.name,
    required this.lowerName,
    required this.attributes,
    required this.searchText,
    this.otherNumbers = const [],
    this.otherImages = const {},
  });

  final String name;
  final Map<String, String> attributes;

  /// The name, lowercased once so searching stays cheap.
  final String lowerName;

  /// Lowercased name and card number, so a search matches either.
  final String searchText;

  String? get cardNo => attributes['cardNo'];

  /// The numbers of this card's other printings, if it has any.
  ///
  /// A deck can name any printing, so all of them have to find the card. They
  /// are kept out of [attributes] because they are for looking the card up,
  /// not for showing.
  final List<String> otherNumbers;

  /// Every number this card has been printed under, the shown one first.
  /// The Japanese numbers this card is printed under where they name a
  /// different card in English: Japanese DZ-SS15/010 is Dragon Monk, Gojo,
  /// English DZ-SS15/010 a Magnides. Read only for a Japanese deck.
  List<String> get japaneseNumbers => [
    for (final number in (attributes['jp'] ?? '').split(','))
      if (number.trim().isNotEmpty) number.trim(),
  ];

  Iterable<String> get allNumbers => [
    if (cardNo != null && cardNo!.isNotEmpty) cardNo!,
    ...otherNumbers,
  ];

  /// The artwork of other printings, by number, where it differs from
  /// [attributes]'s own `imageUrl`. Most reprints reuse the same art, so this
  /// is usually empty even for a card with several [otherNumbers].
  final Map<String, String> otherImages;

  /// The artwork for the printing named [number].
  ///
  /// A deck can name any printing of a card, and different printings can
  /// carry different art -- so showing the printing the catalogue happens to
  /// prefer is wrong whenever a deck names a different one. Falls back to the
  /// card's own image when [number] is null, unknown, or shares its art.
  String? imageFor(String? number) {
    if (number != null) {
      final alternate = otherImages[number];
      if (alternate != null) return alternate;
    }
    return attributes['imageUrl'];
  }

  static const _aliases = <String, String>{
    'g': 'grade',
    't': 'cardType',
    'tr': 'trigger',
    'na': 'nation',
    'c': 'clan',
    'p': 'power',
    's': 'shield',
    'no': 'cardNo',
    'e': 'effect',
    'i': 'imageUrl',
    'sr': 'series',
    'sp': 'possibleSeries',
  };

  /// A card not on the English list yet carries its picture's whole address.
  static String _imageUrl(String imageBase, String image) =>
      image.startsWith('https://') ? image : '$imageBase$image';

  /// [imageBase] is the shared prefix the catalog strips from image URLs to
  /// keep the asset small; it is put back here so the rest of the app only
  /// ever sees a complete URL.
  static CatalogCard fromJson(
    Map<String, dynamic> json, {
    String imageBase = '',
  }) {
    final name = json['n'] as String? ?? '';
    final others = [
      for (final number in json['no2'] as List? ?? const []) '$number',
    ];
    final images = json['i2'] as Map? ?? const {};
    final otherImages = <String, String>{
      for (final entry in images.entries)
        '${entry.key}': _imageUrl(imageBase, '${entry.value}'),
    };
    final attributes = <String, String>{};
    for (final entry in json.entries) {
      if (entry.key == 'n' ||
          entry.key == 'no2' ||
          entry.key == 'i2' ||
          entry.value == null) {
        continue;
      }
      final key = _aliases[entry.key] ?? entry.key;
      final value = '${entry.value}';
      attributes[key] = key == 'imageUrl' ? _imageUrl(imageBase, value) : value;
    }
    final lowerName = name.toLowerCase();
    final cardNo = (attributes['cardNo'] ?? '').toLowerCase();
    return CatalogCard(
      name: name,
      lowerName: lowerName,
      attributes: attributes,
      searchText: cardNo.isEmpty ? lowerName : '$lowerName $cardNo',
      otherNumbers: others,
      otherImages: otherImages,
    );
  }
}

/// Parsed off the UI thread, because the Vanguard catalog runs to megabytes.
List<CatalogCard> parseCatalog(String raw) {
  final json = jsonDecode(raw) as Map<String, dynamic>;
  final imageBase = json['imageBase'] as String? ?? '';
  return (json['cards'] as List)
      .whereType<Map<String, dynamic>>()
      .map((card) => CatalogCard.fromJson(card, imageBase: imageBase))
      .toList(growable: false);
}

/// Loads and searches the bundled card catalogs.
class CardCatalog {
  final _cache = <String, List<CatalogCard>>{};
  final _loading = <String, Future<List<CatalogCard>>>{};

  bool isLoaded(String assetPath) => _cache.containsKey(assetPath);

  int countOf(String assetPath) => _cache[assetPath]?.length ?? 0;

  /// Installs a catalog directly, so tests do not have to read and parse the
  /// real multi-megabyte asset.
  @visibleForTesting
  void seed(String assetPath, List<CatalogCard> cards) {
    _cache[assetPath] = cards;
  }

  /// Loads a catalog once and keeps it. Concurrent callers share one load.
  Future<List<CatalogCard>> load(String assetPath) {
    final cached = _cache[assetPath];
    if (cached != null) return Future.value(cached);

    return _loading[assetPath] ??= () async {
      try {
        final raw = await rootBundle.loadString(assetPath);
        final cards = await compute(parseCatalog, raw);
        _cache[assetPath] = cards;
        return cards;
      } on Exception {
        // A missing or malformed catalog must not take the app down. The
        // screens fall back to entering cards by hand.
        _cache[assetPath] = const [];
        return const <CatalogCard>[];
      } finally {
        _loading.remove(assetPath);
      }
    }();
  }

  /// Cards matching [query], best matches first.
  ///
  /// Ranking runs exact name, then name prefix, then a word inside the name,
  /// then anything else containing the query, which is what matches a card
  /// number. An empty query with a filter set browses that filter's cards.
  static List<CatalogCard> search(
    List<CatalogCard> cards,
    String query, {
    Map<String, String> filters = const {},
    int limit = 60,
  }) {
    final needle = query.trim().toLowerCase();
    final active = {
      for (final filter in filters.entries)
        if (filter.value.isNotEmpty) filter.key: filter.value,
    };
    if (needle.isEmpty && active.isEmpty) return const [];

    // The words typed, for a search that missed by a letter or two --
    // "Zypsophilia" for Zypsophila -- or has its words in another order.
    final words = _words(needle);
    final fuzzy = words.isNotEmpty && words.any((w) => w.length >= 4);

    final ranked = <_Ranked>[];
    for (final card in cards) {
      var keep = true;
      for (final filter in active.entries) {
        if (card.attributes[filter.key] != filter.value) {
          keep = false;
          break;
        }
      }
      if (!keep) continue;

      if (needle.isEmpty) {
        ranked.add(_Ranked(3, card));
        continue;
      }

      final name = card.lowerName;
      int? rank;
      if (name == needle) {
        rank = 0;
      } else if (name.startsWith(needle)) {
        rank = 1;
      } else if (name.contains(' $needle')) {
        rank = 2;
      } else if (card.searchText.contains(needle)) {
        rank = 3;
      } else if (fuzzy && _nearly(words, _words(name))) {
        // After every exact match: a near one is only a suggestion.
        rank = 4;
      }
      if (rank != null) ranked.add(_Ranked(rank, card));
    }

    ranked.sort((a, b) {
      final byRank = a.rank.compareTo(b.rank);
      if (byRank != 0) return byRank;
      return a.card.lowerName.compareTo(b.card.lowerName);
    });

    return [for (final entry in ranked.take(limit)) entry.card];
  }
}

class _Ranked {
  const _Ranked(this.rank, this.card);

  final int rank;
  final CatalogCard card;
}

final _wordSplit = RegExp(r"[^a-z0-9\u3040-\u30ff\u4e00-\u9fff]+");

List<String> _words(String text) => [
  for (final word in text.split(_wordSplit))
    if (word.isNotEmpty) word,
];

/// Whether every word typed is in [name], allowing for a typo: a word of
/// four letters or more may be one letter out, one of eight or more two.
bool _nearly(List<String> typed, List<String> name) {
  for (final word in typed) {
    final allowed = word.length >= 8
        ? 2
        : word.length >= 4
        ? 1
        : 0;
    final found = name.any(
      (each) =>
          each.contains(word) ||
          (allowed > 0 && _withinEdits(word, each, allowed)),
    );
    if (!found) return false;
  }
  return true;
}

/// Whether [a] can be made into [b] with at most [limit] single-letter
/// insertions, deletions or changes.
bool _withinEdits(String a, String b, int limit) {
  if ((a.length - b.length).abs() > limit) return false;
  var previous = List<int>.generate(b.length + 1, (i) => i);
  for (var i = 1; i <= a.length; i += 1) {
    final current = List<int>.filled(b.length + 1, 0)..[0] = i;
    var best = current[0];
    for (var j = 1; j <= b.length; j += 1) {
      final cost = a.codeUnitAt(i - 1) == b.codeUnitAt(j - 1) ? 0 : 1;
      final value = [
        previous[j] + 1,
        current[j - 1] + 1,
        previous[j - 1] + cost,
      ].reduce((x, y) => x < y ? x : y);
      current[j] = value;
      if (value < best) best = value;
    }
    if (best > limit) return false;
    previous = current;
  }
  return previous[b.length] <= limit;
}
